FAMILIES={}
def register(slug,group,method,decision,nearest,indices=range(10),prerequisites=()):
 def dec(fn):
  fid='quality-integration-olympiad-'+slug
  FAMILIES[fid]={'familyId':fid,'topic':'integration','difficulty':'olympiad','finiteInstanceIndices':list(indices),'relatedIdeaGroupId':group,'primaryTechnique':method,'difficultyRationale':decision,'nearestNeighbor':nearest,'prerequisites':list(prerequisites),'sourceRecordIds':[],'constructorVersion':'quality-integration-new-v1','fn':fn}
  return fn
 return dec
def catalog():return [{k:v for k,v in f.items() if k!='fn'} for f in FAMILIES.values()]
def build(fid,i):
 if fid not in FAMILIES or type(i)is not int or i not in FAMILIES[fid]['finiteInstanceIndices']:raise ValueError('Outside reviewed finite domain')
 return FAMILIES[fid]['fn'](fid,i)
def numeric(fid,i,Q,A,wrongs,steps,checks,certificate,parameters):
 meta={k:v for k,v in FAMILIES[fid].items() if k!='fn'};options,correct=numeric_options(A,wrongs,i,fid)
 return package(meta,i,Q,options,correct,steps+[L(A)],checks,certificate,parameters=parameters)

BRANCH_CASES=[([-1,1],[1,2],2),([-2,0,1],[1,1,3],3),([-1,0,2],[2,3,1],4),([-3,-1,2],[1,4,2],5),([-2,1,3],[3,1,2],6),([-2,-1,1,3],[1,2,1,3],2),([-3,0,1,2],[2,1,4,1],3),([-2,0,1,4],[1,3,2,1],4),([-4,-1,1,2],[2,2,1,4],5),([-3,-1,2,4],[3,1,2,2],6)]
@register('rational-inverse-branch-trace','positive-residue-rational-branch-trace','inverse-branch-trace-and-positive-change-of-variables','A rational map has several real inverse branches; their positive derivatives must be summed using the root trace before changing variables.','AGM Landen substitution: here the unweighted trace of every inverse branch replaces the specific quadratic weighted identity.',prerequisites=['monotone change of variables','Vieta formulas','improper integrals'])
def inverse_branches(fid,i):
 poles,weights,m=BRANCH_CASES[i];count=len(poles);rat=x-sum(s.Rational(c)/(x-a) for a,c in zip(poles,weights));Qpoly=s.prod(x-a for a in poles);yy=s.symbols('y',real=True);P=s.expand((x-yy)*Qpoly-sum(c*s.cancel(Qpoly/(x-a)) for a,c in zip(poles,weights)))
 A=s.pi*s.binomial(2*m-2,m-1)/4**(m-1)
 wrong=[((count+1)*A,'Multiply by the number of inverse branches without summing their Jacobians'),(A/(count+1),'Average rather than sum the positive branch Jacobians'),(A/2,'Keep only half of the real line'),(2*A,'Count the two real-line orientations twice'),(s.pi*s.binomial(2*m,m)/4**m,'Increase the transformed denominator power by one'),(s.pi*s.binomial(2*m-4,m-2)/4**(m-2),'Decrease the transformed denominator power by one')]
 statement=r'R(x)='+L(rat)+r'.\quad '+T('At each pole of R, set the following integrand equal to zero. Evaluate the integral over the real line.')+r'\quad\int_{-\infty}^{\infty}\frac{\mathrm{d}x}{(1+R(x)^2)^{'+str(m)+r'}}.'
 steps=[T('Keep all inverse branches of the displayed rational map. Write its poles and positive weights in the following general form.'),r'R(x)=x-\sum_{j=1}^{s}\frac{c_j}{x-a_j},\qquad a_1<\cdots<a_s,\quad c_j>0.',r'R\prime(x)=1+\sum_{j=1}^{s}\frac{c_j}{(x-a_j)^2}>0.',T('On every interval between successive poles, including the two unbounded intervals, the map increases from negative infinity to positive infinity. Thus each real y has exactly s plus one simple real preimages.'),r'Q(x)=\prod_{j=1}^{s}(x-a_j),\qquad P_y(x)=(x-y)Q(x)-\sum_{j=1}^{s}c_j\frac{Q(x)}{x-a_j}.',T('No pole is a zero of this polynomial. Its roots are exactly the preimages. The coefficient of its second-highest power gives their sum.'),r'P_y(x)=x^{s+1}-\left(y+\sum_{j=1}^{s}a_j\right)x^s+\cdots,\qquad\sum_{j=1}^{s+1}x_j(y)=y+\sum_{j=1}^{s}a_j.',T('The inverse function theorem gives positive inverse derivatives. Differentiating the finite root sum makes their sum exactly one.'),r'x_j\prime(y)=\frac1{R\prime(x_j(y))}>0,\qquad\sum_{j=1}^{s+1}x_j\prime(y)=1.',r'g(y)=\frac1{(1+y^2)^{'+str(m)+r'}},\qquad\int_{\mathbb R}g(R(x))\,\mathrm{d}x=\int_{\mathbb R}g(y)\sum_jx_j\prime(y)\,\mathrm{d}y=\int_{\mathbb R}g(y)\,\mathrm{d}y.',T('The branch substitutions are valid first on bounded image intervals; nonnegativity permits the improper limit. A tangent substitution reduces the remaining integral to the standard cosine-power recurrence.'),r'\int_{\mathbb R}\frac{\mathrm{d}y}{(1+y^2)^m}=\int_{-\pi/2}^{\pi/2}\cos^{2m-2}t\,\mathrm{d}t=\pi\frac{\binom{2m-2}{m-1}}{4^{m-1}}\quad(m\in\mathbb Z_{\ge1}).',r'\pi\frac{\binom{'+str(2*m-2)+'}{'+str(m-1)+r'}}{4^{'+str(m-1)+r'}}='+L(A)]
 checks=[eq('Polynomial-clearing identity',s.cancel((rat-yy)*Qpoly),P),eq('Root trace coefficient',P.coeff(x,count),-(yy+sum(poles))),eq('Strictly positive rational derivative representation',s.diff(rat,x),1+sum(s.Rational(c)/(x-a)**2 for a,c in zip(poles,weights))),truth('Distinct poles and strictly positive weights',len(set(poles))==count and all(c>0 for c in weights))]
 certificate=['Each pole has nonzero positive residue parameter and the poles are distinct. One-sided endpoint limits and the displayed positive derivative give a bijection on each pole interval. P_y has degree s+1 and cannot vanish at a pole; its s+1 real simple roots are precisely those branches. Vieta plus the inverse function theorem proves the Jacobian sum. The nonnegative transformed integrand is integrable, so monotone convergence on bounded y-intervals justifies the entire improper identity. Near a pole the displayed integrand tends to zero as a positive even power; at infinity it decays as x^(-2m). The cosine-power recurrence follows by integration by parts with vanishing endpoint terms; its base case is the interval length pi.']
 return numeric(fid,i,statement,A,wrong,steps,checks,certificate,{'poles':poles,'positiveWeights':weights,'basePower':m,'normalizedCapacityKey':'pole-geometry:'+str(poles)+';weights:'+str(weights)+';power:'+str(m),'purposefulCase':'Vary pole count, uneven gaps, positive residue geometry and the transformed rational moment; no common scalar multiplication of a fixed displayed integral.'})

@register('monic-L1-polynomial-extremum','monic-polynomial-L1-sign-duality','sign-orthogonality-and-sharp-L1-duality','A sign function annihilating all lower-degree polynomials proves the global L1 optimum; equality forces every sign-change root and gives the unique minimizer.','The absolute Chebyshev-U integral is a prerequisite; L1 minimization and uniqueness differ from evaluating one fixed polynomial or the Chebyshev-T uniform minimax problem.',indices=range(12),prerequisites=['polynomial degree','trigonometric orthogonality','integral inequalities'])
def monic_l1(fid,i):
 n=i+5;power=1-n;coefnum=n-1;A=s.Tuple(s.Integer(2)**power,-R(coefnum,4));wrongpower=power+(1 if i%2==0 else -1);wrongnum=n if (i//2)%2==0 else n-2
 vals=[]
 for e,c in [(power,coefnum),(power,wrongnum),(wrongpower,coefnum),(wrongpower,wrongnum)]:
  value=s.Tuple(s.Integer(2)**e,-R(c,4));math=r'\left(2^{'+str(e)+r'},\ '+L(-R(c,4))+r'\right)'
  why='correct' if value==A else ('Use the uniform Chebyshev-T coefficient instead of the L1 coefficient' if c==n else 'Apply the polynomial coefficient recurrence one degree too early' if c!=coefnum else 'Lose the full-interval factor in the absolute sine-lobe integral')
  if value!=A and e!=power and c!=coefnum:why='Combine the interval-normalization error with the wrong polynomial coefficient recurrence'
  vals.append((s.srepr(value),math,why))
 final=vals[0][1]
 Q=T('Among real monic polynomials p of the displayed degree, let M be the minimum integral below. Its minimizing polynomial is unique; let c be its coefficient of the indicated power. Find the ordered pair.')+r'\quad\deg p='+str(n)+r',\qquad M=\min_p\int_{-1}^{1}|p(x)|\,\mathrm{d}x,\qquad c=[x^{'+str(n-2)+r'}]p(x),\qquad(M,c)=?'
 steps=[T('Use a polynomial whose sign is orthogonal to every polynomial of smaller degree. Define the second-kind Chebyshev polynomials by their recurrence.'),r'U_0(x)=1,\quad U_1(x)=2x,\quad U_{j+1}(x)=2xU_j(x)-U_{j-1}(x),\quad U_j(\cos t)=\frac{\sin((j+1)t)}{\sin t}.',r'n='+str(n)+r',\qquad q(x)=2^{-n}U_n(x),\qquad \sigma(x)=\operatorname{sgn}(U_n(x)).',T('The leading coefficient of U is two to its degree, so q is monic. Under x equal to cosine t, every lower-degree monomial times the Jacobian is a finite linear combination of sine modes of frequency at most n.'),r'\int_{-1}^{1}x^j\sigma(x)\,\mathrm{d}x=\int_0^\pi\cos^j t\sin t\,\operatorname{sgn}(\sin((n+1)t))\,\mathrm{d}t=0\quad(0\le j<n).',T('Indeed, the square-wave sign has only odd multiples of frequency n plus one in its sine expansion; sine orthogonality eliminates every lower frequency. Equivalently, integrating separately on its finitely many sign intervals gives the same identities.'),T('The difference between any monic p and q has degree below n. The sign moment identities therefore give a universal lower bound.'),r'\int_{-1}^{1}|p(x)|\,\mathrm{d}x\ge\int_{-1}^{1}p(x)\sigma(x)\,\mathrm{d}x=\int_{-1}^{1}q(x)\sigma(x)\,\mathrm{d}x=\int_{-1}^{1}|q(x)|\,\mathrm{d}x.',r'\int_{-1}^{1}|q(x)|\,\mathrm{d}x=2^{-n}\int_0^\pi|\sin((n+1)t)|\,\mathrm{d}t=2^{1-n}.',T('Equality requires p to have the sign of U almost everywhere. At every simple interior zero of U its sign changes, so continuity forces a zero of p there. There are n such distinct roots; monicity forces p to equal q.'),r'p(x)=2^{-n}U_n(x)=x^n-\frac{n-1}{4}x^{n-2}+\textnormal{terms of lower degree}.',T('The displayed next-to-leading coefficient follows by substituting the leading two coefficients into the recurrence.'),r'(M,c)='+final,final]
 U=s.Poly(s.chebyshevu(n,x),x);checks=[eq('Leading coefficient establishes monicity',U.LC(),2**n),eq('Second nonzero coefficient',U.nth(n-2)/2**n,-R(n-1,4)),eq('Absolute sine-lobe total',sum(R(2,n+1) for _ in range(n+1)),2)]
 certificate=['The sign of sin((n+1)t) has its usual L2 sine expansion with frequencies (2r+1)(n+1). Multiplication by the finite sine polynomial sin(t)cos(t)^j permits orthogonality term by term by L2 convergence, not an unjustified pointwise boundary interchange. The finitely many roots cos(k*pi/(n+1)),1<=k<=n, are simple and interior. The nonnegative defect |p|-p*sigma has zero integral only if it vanishes almost everywhere; continuity on each sign interval then forces the required alternating signs. Consequently all n interior roots belong to p, proving uniqueness. The independent verifier checks every finite sign moment directly in the cyclotomic field, without using the Fourier argument.']
 meta={k:v for k,v in FAMILIES[fid].items() if k!='fn'}
 return package(meta,i,Q,vals,s.srepr(A),steps,checks,certificate,parameters={'degree':n,'normalizedCapacityKey':'monic-degree:'+str(n),'purposefulCase':'Changing polynomial degree changes the constrained approximation space and the complete set of sign-change interpolation conditions; no scalar rescaling identifies these tasks.'})

