def cross(a,b,c):return (b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])
def hull(points):
 points=sorted(set(map(tuple,points)));lower=[];upper=[]
 for p in points:
  while len(lower)>1 and cross(lower[-2],lower[-1],p)<=0:lower.pop()
  lower.append(p)
 for p in reversed(points):
  while len(upper)>1 and cross(upper[-2],upper[-1],p)<=0:upper.pop()
  upper.append(p)
 return lower[:-1]+upper[:-1]
def distance(a,b):return s.sqrt((a[0]-b[0])**2+(a[1]-b[1])**2)
def pointtex(points):return r'\{'+r',\ '.join(r'('+str(a)+','+str(b)+')' for a,b in points)+r'\}'
@register('support-function-perimeter','convex-support-angular-perimeter','support-switching-and-polygon-boundary','The maximum over finitely many oscillating linear forms hides the support function of a convex hull; the angular integral telescopes to its perimeter.','Ordinary piecewise trigonometric integration is possible, but finding active vertices and their switching normals is the essential geometric decision.',indices=range(12),prerequisites=['convex hull','dot products','piecewise integration'])
def support_perimeter(fid,i):
 points=HULL_CASES[i];vertices=hull(points);n=len(vertices);P=s.simplify(sum(distance(vertices[j],vertices[(j+1)%n]) for j in range(n)));box=2*(max(a for a,b in points)-min(a for a,b in points)+max(b for a,b in points)-min(b for a,b in points));triangle=sum(distance(vertices[j],vertices[k]) for j,k in [(0,n//3),(n//3,2*n//3),(2*n//3,0)]);listed=sum(distance(points[j],points[(j+1)%len(points)]) for j in range(len(points)))
 wrong=[(P/2,'Take half the support integral as if the question asked its mean width'),(2*P,'Count both support and opposite-support integrals twice'),(s.Integer(box),'Replace the convex hull by its axis-aligned bounding rectangle'),(s.Rational(box,2),'Retain only one horizontal and one vertical width'),(triangle,'Discard active vertices and use only an inscribed triangle'),(listed,'Connect all listed points in their supplied order, including interior points')]
 Q=r'\mathcal P='+pointtex(points)+r',\qquad h(\theta)=\max_{(a,b)\in\mathcal P}(a\cos\theta+b\sin\theta).\quad'+T('Evaluate the angular integral.')+r'\quad\int_0^{2\pi}h(\theta)\,\mathrm{d}\theta.'
 edge_math='+'.join(L(distance(vertices[j],vertices[(j+1)%n])) for j in range(n))
 steps=[T('Only vertices of the convex hull can maximize a linear functional. Removing the inactive points and ordering the boundary counterclockwise gives these vertices.'),r'(v_1,\ldots,v_s)=\left('+r',\ '.join(r'('+str(a)+','+str(b)+')' for a,b in vertices)+r'\right),\qquad v_{s+1}=v_1.',T('Let each boundary edge be e and let its outward unit normal have angle alpha. Write the unit direction and a chosen vector antiderivative as follows.'),r'u(\theta)=(\cos\theta,\sin\theta),\quad w(\theta)=(\sin\theta,-\cos\theta),\quad w\prime(\theta)=u(\theta).',r'e_j=v_{j+1}-v_j,\quad u(\alpha_j)=\frac{((e_j)_2,-(e_j)_1)}{|e_j|},\quad w(\alpha_j)=-\frac{e_j}{|e_j|}.',T('Between the outward normals of two successive edges, their common vertex maximizes the dot product. Integrating that linear form on each such angular interval and then summing gives a telescoping boundary expression.'),r'\int_0^{2\pi}h(\theta)\,\mathrm{d}\theta=\sum_{j=1}^{s}v_j\cdot\big(w(\alpha_j)-w(\alpha_{j-1})\big)=\sum_{j=1}^{s}(v_j-v_{j+1})\cdot w(\alpha_j).',r'(v_j-v_{j+1})\cdot w(\alpha_j)=(-e_j)\cdot\frac{-e_j}{|e_j|}=|e_j|.',T('Thus the integral is the convex hull perimeter. No assumption that the origin lies in the hull is needed: translating all points adds a linear combination of sine and cosine with zero full-period integral.'),r'\int_0^{2\pi}h(\theta)\,\mathrm{d}\theta='+edge_math+'='+L(P)]
 checks=[truth('Every displayed point lies in all counterclockwise hull half-planes',all(cross(vertices[j],vertices[(j+1)%n],p)>=0 for j in range(n) for p in points)),truth('Every retained boundary turn is strictly convex',all(cross(vertices[j-1],vertices[j],vertices[(j+1)%n])>0 for j in range(n))),eq('Boundary primitive edge contribution',sum((vertices[j][0]-vertices[(j+1)%n][0])*(vertices[j][0]-vertices[(j+1)%n][0])/distance(vertices[j],vertices[(j+1)%n])+(vertices[j][1]-vertices[(j+1)%n][1])*(vertices[j][1]-vertices[(j+1)%n][1])/distance(vertices[j],vertices[(j+1)%n]) for j in range(n)),P)]
 ds=sorted((a[0]-b[0])**2+(a[1]-b[1])**2 for a,b in itertools.combinations(vertices,2));shape=[str(R(v,ds[0])) for v in ds]
 certificate=['A linear functional reaches its maximum over a finite set on its convex hull. Strict positive hull turns and all-point half-plane checks certify the displayed boundary and redundant points. The outward edge normals partition the unit circle into intervals on which the active vertex is fixed; boundaries of those intervals have measure zero. The vector primitive calculation is exact on each closed subinterval, and summing cyclic endpoints gives the perimeter. Nonempty finite polygons give continuous support functions, so no improper-integral or convergence hypothesis is needed.']
 return numeric(fid,i,Q,P,wrong,steps,checks,certificate,{'points':points,'hullVertices':vertices,'normalizedCapacityKey':'normalized-pairwise-hull-distances:'+str(shape),'purposefulCase':'Distinct nonsimilar convex-hull geometries with different active-vertex counts, uneven edges and redundant points; translations, rotations and scalar copies are not counted separately.'})

WELL_CASES=[(1,2,0),(2,1,-R(1,6)),(1,3,R(1,6)),(3,2,0),(3,1,-R(1,6)),(3,2,R(1,6)),(4,2,0),(4,2,-R(1,8)),(1,4,R(1,8)),(4,3,0),(4,1,-R(1,10)),(4,3,R(1,10))]
@register('competing-laplace-wells','competing-degenerate-Laplace-wells','multiwell-localization-and-logarithmic-tilt','Two zeros of different degeneracy contribute on different scales; a logarithmic tilt can select one well or balance both, and the endpoint contributes half-line mass.','The retained boundary-layer family has a single endpoint and one direct rescaling; this construction needs competing localization scales and a regime decision.',indices=range(12),prerequisites=['dominated convergence','Gamma integral','asymptotic equivalence'])
def competing_wells(fid,i):
 p,q,offset=WELL_CASES[i];critical=R(1,2*q)-R(1,2*p);tau=critical+offset;C0=2*s.gamma(1+R(1,2*p));C1=s.gamma(1+R(1,2*q));mix=s.simplify(C1/(C0+C1));answer=s.Integer(0) if offset<0 else s.Integer(1) if offset>0 else mix
 swapped=s.simplify((C0/2)/(2*C1+C0/2))
 options,code=numeric_options(answer,[(v,why) for v,why in [(s.Integer(0),'Keep only the interior well despite the relative tilted scale'),(s.Integer(1),'Keep only the endpoint well despite the relative tilted scale'),(mix,'Assume the two well masses have the same power of n'),(swapped,'Swap the two local degeneracy orders while retaining their full-line and half-line roles')]],i,fid)
 oldkey=digest([[(c,t) for c,t,_ in options],code])
 def gtex(k):return r'\Gamma\!\left('+L(1+R(1,2*k))+r'\right)'
 def mixtex(j,k):return r'\frac{'+gtex(k)+r'}{2'+gtex(j)+'+'+gtex(k)+'}'
 options=[(c,mixtex(p,q) if c==s.srepr(mix) else mixtex(q,p) if c==s.srepr(swapped) else t,why) for c,t,why in options]
 OPTION_AUDITS[digest([[(c,t) for c,t,_ in options],code])]=OPTION_AUDITS[oldkey]
 final=next(v[1] for v in options if v[0]==code)
 phase=x**(2*p)*(1-x)**(2*q)
 Q=r'V(x)='+L(phase)+r',\qquad w_n(x)=n^{('+L(tau)+r')x}e^{-nV(x)}\quad(-1\le x\le1,\ n\in\mathbb Z_{\ge1}).\quad '+T('Find the limit of the normalized first moment.')+r'\quad\lim_{n\to\infty}\frac{\int_{-1}^{1}xw_n(x)\,\mathrm{d}x}{\int_{-1}^{1}w_n(x)\,\mathrm{d}x}.\qquad\Gamma(a)=\int_0^\infty t^{a-1}e^{-t}\,\mathrm{d}t\quad(a>0).'
 resultprose='The interior well has the larger asymptotic mass, so the first moment tends to its location zero.' if offset<0 else 'The endpoint well has the larger asymptotic mass, so the first moment tends to its location one.' if offset>0 else 'The two powers match. The limiting first moment is the endpoint mass divided by the sum of both local masses.'
 steps=[T('The phase is nonnegative and vanishes only at the interior point zero and the endpoint one. Their orders determine different localization scales.'),r'2p='+str(2*p)+r',\quad2q='+str(2*q)+r',\quad\tau='+L(tau)+r',\qquad V(x)\sim x^{2p}\ (x\to0),\quad V(x)\sim(1-x)^{2q}\ (x\to1).',T('Near zero put x equal to n to the power minus one over two p times u. Near one put one minus x equal to n to the power minus one over two q times v. The logarithmic tilt is asymptotically constant on each rescaled neighborhood.'),r'n^{\tau x}=\exp(\tau x\ln n),\qquad n^{-1/(2p)}\ln n\to0,\quad n^{-1/(2q)}\ln n\to0.',T('Let J zero and J one denote the masses in fixed small neighborhoods of zero and one, respectively.'),r'J_0(n)\sim C_0n^{-1/(2p)},\quad C_0=\int_{-\infty}^{\infty}e^{-u^{2p}}\,\mathrm{d}u=2\Gamma\!\left(1+\frac1{2p}\right),',r'J_1(n)\sim C_1n^{\tau-1/(2q)},\quad C_1=\int_0^\infty e^{-v^{2q}}\,\mathrm{d}v=\Gamma\!\left(1+\frac1{2q}\right).',T('Away from both neighborhoods the phase has a positive minimum, so the exponential decay defeats every fixed power from the tilt.'),T('For the local dominated limits, the phase bounds give an exponential of a negative even power. The residual tilted linear term has a coefficient tending to zero, and can be absorbed into half that negative power plus a fixed constant. This supplies an integrable bound.'),r'\frac{J_1(n)}{J_0(n)}\sim\frac{C_1}{C_0}n^{\Delta},\qquad\Delta=\tau+\frac1{2p}-\frac1{2q}='+L(offset)+'.',T('The factor x in the numerator tends to zero at the first well and one at the second. It is bounded, so the same domination justifies those weighted limits.'),r'\frac{\int_{-1}^{1}xw_n(x)\,\mathrm{d}x}{\int_{-1}^{1}w_n(x)\,\mathrm{d}x}=\frac{J_1(n)+o(J_0(n)+J_1(n))}{J_0(n)+J_1(n)+o(J_0(n)+J_1(n))}.',T(resultprose)]
 if offset==0:steps.append(r'\frac{C_1}{C_0+C_1}=\frac{'+L(C1)+r'}{'+L(C0)+r'+'+L(C1)+r'}='+final)
 steps.append(final)
 checks=[eq('Interior phase coefficient',s.Poly(phase,x).nth(2*p),1),eq('Endpoint phase coefficient',s.Poly(s.expand(phase.subs(x,1-x)),x).nth(2*q),1),eq('Relative power after including logarithmic tilt',tau+R(1,2*p)-R(1,2*q),offset),truth('Local powers positive and even',p>=1 and q>=1)]
 certificate=['Choose disjoint fixed neighborhoods of0 and1 inside[-1,1]. The polynomial has no other zeros, so its minimum on the remaining compact set is positive. Near each well its ratio to the leading even power tends to1 and stays bounded below by a positive constant. After rescaling, the tilt remainder is b_n times the local variable with b_n tending to0. For sufficiently large n, |b_n u| is at most half the leading negative even power plus a uniform finite constant, giving a global integrable rescaled majorant. The interior neighborhood expands to the whole real line; the endpoint neighborhood expands only to the positive half-line. Gamma substitution and recurrence evaluate the two constants. Dominated convergence also applies with the bounded multiplier x. Comparing the exact rational relative exponent proves the three requested regimes.']
 meta={k:v for k,v in FAMILIES[fid].items() if k!='fn'}
 return package(meta,i,Q,options,code,steps,checks,certificate,parameters={'interiorHalfOrder':p,'endpointHalfOrder':q,'tilt':str(tau),'relativePower':str(offset),'normalizedCapacityKey':'orders:'+str((p,q))+';regime:'+str(s.sign(offset)),'purposefulCase':'Varies both well degeneracies and whether the tilt is below, at or above the exact competing-scale threshold; the asymmetry of an interior versus endpoint well is retained.'})

BATHTUB_CASES=[(R(1,2),R(1,8)),(R(2,3),R(1,6)),(R(2,5),R(1,10)),(R(3,5),R(1,5)),(R(3,4),R(1,4)),(R(1,3),R(1,9)),(R(4,5),R(3,10)),(R(3,7),R(1,7)),(R(5,7),R(2,7)),(R(4,7),R(1,7))]
@register('capped-two-moment-extrema','bounded-density-two-moment-bathtub','quadratic-dual-sign-and-free-boundaries','Two integral constraints determine the active sets of a capped density. Quadratic dual certificates prove both extrema and their attainment.','The existing rearrangement construction fixes a value distribution; here mass and first moment are the only constraints and both unknown support boundaries must be solved.',prerequisites=['integral inequalities','polynomial sign','measurable functions'])
def bathtub(fid,i):
 mass,right=BATHTUB_CASES[i];left=mass-right;moment=mass**2/2+right*(1-mass);a=moment/mass-mass/2;b=a+mass
 lo=s.simplify((b**3-a**3)/3);hi=s.simplify((left**3+1-(1-right)**3)/3)
 wronglo=moment**2/mass+mass**3/(24 if i%2==0 else 6);wronghi=hi-right**3/3 if i%2==0 else hi-left**3/6
 assert moment**2/mass<wronglo<hi and lo<wronghi<moment
 pairs=[(lo,hi),(wronglo,hi),(lo,wronghi),(wronglo,wronghi)];options=[(s.srepr(s.Tuple(*v)),L(s.Tuple(*v)),'correct' if j==0 else 'Use the wrong interval variance factor' if j==1 else 'Omit a cubic endpoint term in the outer support integral' if j==2 else 'Combine both interval-moment errors') for j,v in enumerate(pairs)];final=options[0][1]
 Q=T('Let f range over measurable real functions satisfying the displayed bounds and two integral constraints. Find the ordered pair consisting of the minimum and maximum of J.')+r'\quad0\le f(x)\le1\quad(0\le x\le1),\qquad\int_0^1f(x)\,\mathrm{d}x='+L(mass)+r',\qquad\int_0^1xf(x)\,\mathrm{d}x='+L(moment)+r',\qquad J(f)=\int_0^1x^2f(x)\,\mathrm{d}x.'
 steps=[T('The lower extremizer fills one middle interval; the upper extremizer fills two endpoint intervals. Define the mass and first moment from the question.'),r'M='+L(mass)+r',\quad B='+L(moment)+r',\quad a=\frac BM-\frac M2='+L(a)+r',\quad b=a+M='+L(b)+r'.',T('Let the lower candidate equal one on the interval from a to b and zero elsewhere. Its mass and first moment are the required ones.'),r'f_-(x)=\mathbf1_{[a,b]}(x),\qquad\int_0^1f_-(x)\,\mathrm{d}x=b-a=M,\quad\int_0^1xf_-\,\mathrm{d}x=\frac{b^2-a^2}{2}=B.',T('The quadratic with roots a and b is negative inside this interval and positive outside. The cap on f therefore gives a pointwise sign certificate. Constant and linear terms vanish after integration because the constraints agree.'),r'(x-a)(x-b)(f(x)-f_-(x))\ge0,\qquad J(f)-J(f_-)=\int_0^1(x-a)(x-b)(f-f_-)\,\mathrm{d}x\ge0.',T('For the upper candidate, let its right endpoint interval have length r and its left interval length l. The two constraints give the following lengths.'),r'r=\frac{B-M^2/2}{1-M}='+L(right)+r',\qquad l=M-r='+L(left)+r',\qquad f_+(x)=\mathbf1_{[0,l]\cup[1-r,1]}(x).',r'\int_0^1f_+(x)\,\mathrm{d}x=l+r=M,\qquad\int_0^1xf_+\,\mathrm{d}x=\frac{l^2+2r-r^2}{2}=B.',T('This time the quadratic is positive on the two filled endpoint intervals and negative between them. The same cap reverses the sign certificate.'),r'(x-l)(x-(1-r))(f(x)-f_+(x))\le0,\qquad J(f)-J(f_+)\le0.',T('Both indicator functions are admissible measurable functions, so these are attained extrema. Evaluate their second moments.'),r'J(f_-)=\frac{b^3-a^3}{3}='+L(lo)+r',\qquad J(f_+)=\frac{l^3+1-(1-r)^3}{3}='+L(hi),final]
 checks=[eq('Middle interval mass',b-a,mass),eq('Middle interval first moment',(b*b-a*a)/2,moment),eq('Outer interval mass',left+right,mass),eq('Outer interval first moment',(left*left+2*right-right*right)/2,moment),truth('All four free boundaries lie in the allowed interval',0<a<b<1 and 0<left<1-right<1)]
 cert=['The finite rational parameters give strictly interior, disjoint active sets. Every admissible density is bounded and measurable, so all displayed moments exist. For the minimum, the dual quadratic is negative precisely on the filled middle interval and positive outside; multiplying by f minus the indicator is pointwise nonnegative. For the maximum, the dual quadratic is positive precisely on the filled endpoint intervals, making the corresponding product nonpositive. Its lower-degree terms integrate to zero by the two constraints. This proves global bounds, and the explicitly admissible indicators attain both. No continuity requirement is imposed.']
 return package({k:v for k,v in FAMILIES[fid].items() if k!='fn'},i,Q,options,options[0][0],steps,checks,cert,parameters={'mass':str(mass),'firstMoment':str(moment),'normalizedCapacityKey':'mass:'+str(mass)+';outer-mass-fraction:'+str(min(left,right)/mass),'purposefulCase':'Changes both occupied mass and its asymmetric moment, hence the middle and two-endpoint active supports; reflection-equivalent constraint pairs are not counted separately.'})

HILBERT_CASES=[R(1,3),R(2,5),R(3,7),R(4,9),R(2,7),R(3,8),R(5,11),R(4,11),R(5,13),R(7,15)]
@register('semicircle-interior-pole','semicircle-finite-Hilbert-transform','symmetric-cutoff-and-arcsine-pole-cancellation','A semicircle-weighted singular integral requires preserving the symmetric cutoff through substitution; polynomial division and a logarithmic branch calculation remove the remaining pole.','The retained Mellin principal value uses reciprocal tails and reflection; this compact square-root density has a different transformed kernel and cutoff geometry.',prerequisites=['Cauchy principal value','tangent half-angle substitution','logarithmic primitives'])
def finite_hilbert(fid,i):
 a=HILBERT_CASES[i];A=-s.pi*a
 wrong=[(-s.pi*a/2,'Lose half the interval in the cosine substitution'),(-2*s.pi*a,'Count both cosine orientations twice'),(-s.pi/a,'Invert the moving pole when dividing the numerator'),(-s.pi*s.sqrt(1-a*a),'Keep a false real square-root branch term inside the cut'),(-s.pi*(1-a),'Use distance from the right endpoint instead of the pole coordinate'),(-s.pi*(1+a),'Use distance from the left endpoint instead of the pole coordinate')]
 Q=T('Evaluate the Cauchy principal value defined by the displayed equal-distance cutoffs around the interior pole. The square root is the nonnegative real root.')+r'\quad\lim_{\varepsilon\downarrow0}\left(\int_{-1}^{'+L(a)+r'-\varepsilon}\frac{\sqrt{1-x^2}}{x-'+L(a)+r'}\,\mathrm{d}x+\int_{'+L(a)+r'+\varepsilon}^{1}\frac{\sqrt{1-x^2}}{x-'+L(a)+r'}\,\mathrm{d}x\right).'
 steps=[T('Let I denote the requested principal value and a the displayed pole. Separate the nonsingular polynomial part from the singular arcsine kernel.'),r'a='+L(a)+r',\qquad\frac{\sqrt{1-x^2}}{x-a}=\frac{1-a^2}{(x-a)\sqrt{1-x^2}}-\frac{x+a}{\sqrt{1-x^2}}.',T('The second term integrates directly: its odd part vanishes, while the arcsine mass is pi. It remains to show that the first term has zero principal value.'),r'K(a)=\operatorname{PV}\int_{-1}^{1}\frac{\mathrm{d}x}{(x-a)\sqrt{1-x^2}},\qquad I=(1-a^2)K(a)-a\pi.',T('Use x equal to cosine theta, then the tangent of half theta. The pole is an interior positive point in the new variable.'),r't=\tan(\theta/2),\quad x=\frac{1-t^2}{1+t^2},\quad b=\sqrt{\frac{1-a}{1+a}}>0,\qquad K(a)=\operatorname{PV}\int_0^\infty\frac{2\,\mathrm{d}t}{(1-a)-(1+a)t^2}.',T('A chosen real antiderivative on each side of the pole has the following logarithmic form and vanishes at both external endpoints.'),r'F(t)=\frac1{(1+a)b}\ln\left|\frac{b+t}{b-t}\right|,\quad F\prime(t)=\frac2{(1-a)-(1+a)t^2},\quad F(0)=0,\quad\lim_{t\to\infty}F(t)=0.',T('The original equal x cutoffs need not be equal in t. Their distances from b nevertheless have ratio tending to one, because the inverse substitution has a finite nonzero derivative at the pole. The two logarithmic divergences therefore cancel with no residual constant.'),r't_-=\sqrt{\frac{1-a-\varepsilon}{1+a+\varepsilon}}<b<t_+=\sqrt{\frac{1-a+\varepsilon}{1+a-\varepsilon}},\qquad\frac{b-t_-}{t_+-b}\to1,\qquad F(t_-)-F(t_+)\to0.',r'K(a)=0,\qquad I=-a\pi='+L(A)]
 checks=[eq('Weighted-kernel polynomial division',s.cancel((1-a*a)/(x-a)-(x+a)),s.cancel((1-x*x)/(x-a))),truth('Moving pole is interior and away from symmetry',0<a<1)]
 cert=['The semicircle density is continuous at the interior pole, and its first derivative is bounded near that point. Subtracting its value at the pole leaves a locally bounded quotient, which independently ensures the symmetric principal value exists. At the two external endpoints both the original square-root kernel and the separated arcsine terms are integrable. The cosine and half-angle substitutions are applied first with the exact transformed cutoffs, not with an assumed symmetric new cutoff. The inverse map has nonzero derivative at the pole, so the two new distances have ratio one asymptotically. In the displayed logarithmic primitive, the regular numerators have the same limit; hence the cutoff difference vanishes. This proves the zero arcsine principal value and the stated result.']
 return numeric(fid,i,Q,A,wrong,steps,checks,cert,{'pole':str(a),'normalizedCapacityKey':'semicircle-pole-absolute-position:'+str(a),'purposefulCase':'Distinct interior pole positions relative to the fixed semicircle support; the only reflection equivalence changes the pole sign, and all selected poles are positive.'})

PEANO_CASES=[(R(1,3),R(1,12)),(R(2,5),R(1,10)),(R(3,7),R(1,7)),(R(2,7),R(1,14)),(R(3,8),R(1,8)),(R(4,9),R(1,9)),(R(1,4),R(1,16)),(R(4,11),R(1,11)),(R(1,3),R(1,4)),(R(2,5),R(1,4))]
@register('three-node-Peano-sharpness','peano-kernel-sharp-error','Peano-kernel-sign-and-continuous-extremizers','The optimal quadrature error requires the absolute integral of a piecewise kernel, plus a separate decision whether a continuous second derivative can attain its sign pattern.','The differentiation construction has two symmetric interior nodes; these three-node rules include endpoints, asymmetric weights and both sign-changing and one-sign kernels.',prerequisites=['Taylor integral remainder','sharp norm inequalities','continuous approximation'])
def peano(fid,i):
 a,w0=PEANO_CASES[i];w2=s.simplify((R(1,2)-a+a*w0)/(1-a));w1=1-w0-w2;K0=x*x/2-w0*x;K1=(1-x)**2/2-w2*(1-x);change=2*w0<a
 roots=[s.Integer(0),2*w0,a,1-2*w2,s.Integer(1)] if change else [s.Integer(0),a,s.Integer(1)]
 pieces=[];C=0
 for lo,hi in zip(roots,roots[1:]):
  K=K0 if hi<=a else K1;sign=s.sign(K.subs(x,(lo+hi)/2));value=s.integrate(K,(x,lo,hi));C+=sign*value;pieces.append({'lower':str(lo),'upper':str(hi),'polynomial':str(K),'sign':int(sign)})
 C=s.simplify(C);signed=s.integrate(K0,(x,0,a))+s.integrate(K1,(x,a,1));wrong=abs(signed) if change else 2*C;attained=not change
 def form(v,yes):return r'\left('+L(v)+r',\ \textnormal{'+('yes' if yes else 'no')+r'}\right)'
 combos=[(C,attained),(wrong,attained),(C,not attained),(wrong,not attained)];opts=[(str(v)+';'+str(yes),form(v,yes),'correct' if j==0 else 'Replace the absolute kernel integral by its signed integral' if j==1 and change else 'Double the Taylor remainder contribution' if j==1 else 'Assume a discontinuous kernel sign is an admissible continuous second derivative' if j==2 and change else 'Confuse an admissible quadratic extremizer with a limiting discontinuous sign' if j==2 else 'Combine the constant and attainment mistakes') for j,(v,yes) in enumerate(combos)]
 Q=T('For real twice continuously differentiable f on the unit interval with the displayed derivative bound, define the quadrature error E. Find the ordered pair consisting of its sharp supremum C and the answer yes or no to whether an admissible f attains it.')+r'\quad |f\prime\prime(x)|\le1\quad(0\le x\le1),\qquad E(f)=\int_0^1f(x)\,\mathrm{d}x-\left('+L(w0)+r'f(0)+'+L(w1)+r'f('+L(a)+r')+'+L(w2)+r'f(1)\right),\qquad C=\sup_f|E(f)|.'
 steps=[T('The rule is exact on constants and linear functions, so only the integral remainder in Taylor expansion contributes. Define the interior node and the three weights.'),r'a='+L(a)+r',\qquad (w_0,w_1,w_2)='+L(s.Tuple(w0,w1,w2))+r',\qquad w_0+w_1+w_2=1,\quad aw_1+w_2=\frac12.',r'f(x)=f(0)+xf\prime(0)+\int_0^x(x-t)f\prime\prime(t)\,\mathrm{d}t.',T('Interchange the continuous triangular integral and collect the quadrature evaluations. The resulting kernel is piecewise quadratic.'),r'E(f)=\int_0^1K(t)f\prime\prime(t)\,\mathrm{d}t,\qquad K(t)=\begin{cases}t^2/2-w_0t,&0\le t\le a,\\(1-t)^2/2-w_2(1-t),&a\le t\le1.\end{cases}',r'|E(f)|\le\int_0^1|K(t)|\,\mathrm{d}t.']
 if change:
  steps += [T('The kernel is negative near both endpoints and positive in the middle. Its two interior zeros determine the exact absolute integral.'),r'\rho=2w_0='+L(2*w0)+r',\quad\sigma=1-2w_2='+L(1-2*w2)+r',\quad0<\rho<a<\sigma<1.',r'\int_0^1|K(t)|\,\mathrm{d}t=-\int_0^\rho K(t)\,\mathrm{d}t+\int_\rho^\sigma K(t)\,\mathrm{d}t-\int_\sigma^1K(t)\,\mathrm{d}t='+L(C)+r'.',T('Choose continuous second derivatives bounded by one that agree with the kernel sign outside shrinking neighborhoods of the two zeros. Integrating them twice gives admissible functions; dominated convergence makes their errors tend to this bound.'),T('Equality would require the second derivative to equal the kernel sign almost everywhere, up to one common sign. Continuity would then force opposite one-sided values at each sign-changing zero. This is impossible, so the supremum is not attained.')]
 else:
  steps += [T('The kernel is nonpositive on both pieces. Its absolute integral is therefore the negative signed integral, and the quadratic with second derivative minus one attains the bound.'),r'K(t)\le0,\qquad C=-\int_0^1K(t)\,\mathrm{d}t='+L(C)+r',\qquad f(x)=-x^2/2,\quad E(f)=C.']
 steps.append(opts[0][1])
 checks=[eq('Constant exactness',w0+w1+w2,1),eq('Linear exactness',a*w1+w2,R(1,2)),eq('Kernel continuity at the interior node',K0.subs(x,a),K1.subs(x,a)),truth('Positive quadrature weights and interior node',0<a<1 and all(v>0 for v in [w0,w1,w2]))]
 cert=['Taylor integral remainder holds for every admitted C2 function. Fubini is valid because its integrand is continuous on a compact triangle. The weight identities cancel affine terms exactly. The piecewise kernel is continuous at the node, and its explicitly factored roots determine its sign on every interval. The L-infinity derivative bound gives the L1 kernel upper bound. When the sign changes, continuous bounded approximations to that sign are integrated twice, preserving the derivative bound and yielding a maximizing sequence by dominated convergence. Equality of the norm inequality forces the second derivative to have the common kernel sign wherever the kernel is nonzero; continuity across a genuine sign change rules out attainment. In the one-sign cases a quadratic attains the bound directly.']
 return package({k:v for k,v in FAMILIES[fid].items() if k!='fn'},i,Q,opts,opts[0][0],steps,checks,cert,parameters={'node':str(a),'weights':list(map(str,[w0,w1,w2])),'kernelPieces':pieces,'signChanges':2 if change else 0,'normalizedCapacityKey':'node:'+str(a)+';weights:'+str([w0,w1,w2]),'purposefulCase':'Asymmetric three-node geometries change the two root locations and include both nonattainment and quadratic attainment. No reflection or scalar multiple of a fixed rule is repeated.'})

ENDPOINT_RATIOS=[R(2),R(3),R(4),R(5),R(3,2),R(5,2),R(7,2),R(4,3),R(5,3),R(7,3)]
@register('coupled-endpoint-sharp-energy','coupled-endpoint-Sturm-ground-state','natural-boundary-condition-and-positive-square-completion','A coupled endpoint constraint changes the lowest energy mode; the candidate eigenvalue must be derived and then proved globally sharp by a positive ground-state identity.','The retained variational-energy problem fixes two endpoint values. This homogeneous quotient has an unknown endpoint amplitude and a coupled natural derivative condition.',prerequisites=['integration by parts','trigonometric identities','sharp integral inequalities'])
def coupled_energy(fid,i):
 k=ENDPOINT_RATIOS[i];z=(k-1)/(k+1);alpha=2*s.atan(z);A=alpha**2
 wrong=[(A/4,'Omit the double-angle factor when solving the boundary equation'),(4*A,'Count the half-angle conversion twice'),(s.atan(k)**2,'Use the endpoint ratio itself as the tangent phase'),(4*s.atan(1/k)**2,'Invert the endpoint ratio before the half-angle conversion'),(s.pi**2/4,'Impose a zero endpoint instead of the coupled condition'),(s.pi**2,'Replace the coupled endpoints by two Dirichlet endpoints')]
 Q=T('Find the largest real constant C for which the inequality holds for every real continuously differentiable f on the unit interval satisfying the displayed endpoint relation.')+r'\quad f(1)='+L(k)+r'f(0),\qquad\int_0^1(f\prime(x))^2\,\mathrm{d}x\ge C\int_0^1f(x)^2\,\mathrm{d}x.'
 steps=[T('The endpoint values are coupled rather than fixed. To find a candidate extremizer, vary the energy quotient while preserving that relation. Define k as the endpoint multiplier.'),r'k='+L(k)+r',\qquad -\phi\prime\prime=\lambda\phi,\qquad\phi(1)=k\phi(0),\quad\phi\prime(0)=k\phi\prime(1).',T('The derivative relation is the natural boundary condition: the boundary term from integration by parts must vanish for every variation whose final value is k times its initial value.'),r'\phi\prime(1)\delta\phi(1)-\phi\prime(0)\delta\phi(0)=\big(k\phi\prime(1)-\phi\prime(0)\big)\delta\phi(0).',T('Writing the solution as a combination of cosine and sine gives a two by two homogeneous system. Its determinant vanishes at the following phase.'),r'\lambda=\alpha^2,\quad\phi(x)=A\cos(\alpha x)+B\sin(\alpha x),\qquad\begin{vmatrix}\cos\alpha-k&\sin\alpha\\k\sin\alpha&1-k\cos\alpha\end{vmatrix}=0.',r'(1+k^2)\cos\alpha-2k=0,\qquad\alpha=2\arctan\!\left(\frac{k-1}{k+1}\right)\in(0,\pi/2).',T('A positive candidate is obtained with cosine coefficient one and sine coefficient k. It satisfies both boundary conditions and has no zero on the interval.'),r'\phi(x)=\cos(\alpha x)+k\sin(\alpha x)>0,\quad\phi(1)=k,\quad\phi\prime(0)=k\alpha,\quad\phi\prime(1)=\alpha.',T('Now prove the bound for every admissible function, without assuming that the formal variational calculation found the minimum. Define the logarithmic derivative v and complete a square.'),r'v=\frac{\phi\prime}{\phi},\quad v\prime+v^2=-\alpha^2,\quad v(0)=k\alpha,\quad v(1)=\alpha/k.',r'\int_0^1(f\prime-vf)^2\,\mathrm{d}x=\int_0^1(f\prime)^2\,\mathrm{d}x-\alpha^2\int_0^1f^2\,\mathrm{d}x-\left[vf^2\right]_0^1.',r'\left[vf^2\right]_0^1=\frac\alpha k(kf(0))^2-k\alpha f(0)^2=0.',T('The square proves the desired inequality. Taking f equal to the positive candidate makes it zero, so no larger constant is possible.'),r'C=\alpha^2=4\arctan^2\!\left('+L(z)+r'\right)='+L(A)]
 u=s.symbols('u',real=True);c=(1-z*z)/(1+z*z);ss=2*z/(1+z*z)
 checks=[eq('Half-angle cosine solves the determinant',c,2*k/(1+k*k)),eq('Candidate endpoint value',c+k*ss,k),eq('Candidate endpoint derivative divided by phase',-ss+k*c,1),eq('Boundary square term cancels',(s.Integer(1)/k)*k*k-k,0)]
 cert=['The variational calculation is used only to discover the candidate; global optimality is proved separately by the exact square identity. Since k>1, the chosen phase lies strictly between zero and pi/2, so both cosine and sine contributions make the candidate positive on the full interval. Its logarithmic derivative is continuously differentiable and bounded. Integration by parts in the square identity is valid for every C1 admissible f. The coupled endpoint condition cancels its boundary term exactly. The positive candidate itself is admissible and makes the square vanish, proving attainment and sharpness. Reciprocal endpoint ratios are reflection-equivalent and not included separately.']
 return numeric(fid,i,Q,A,wrong,steps,checks,cert,{'endpointRatio':str(k),'normalizedCapacityKey':'endpoint-ratio-up-to-reciprocal:'+str(k),'purposefulCase':'Distinct dimensionless coupling ratios alter the natural boundary condition and phase. Reflections produce reciprocal ratios; only ratios above one are included.'})

RELAX_MEANS=[R(0),R(1,4),R(1,2),R(3,4),R(1),R(9,8),R(5,4),R(11,8),R(3,2),R(7,4),R(6,5),R(8,5)]
@register('nonconvex-mean-relaxation','double-well-convex-envelope-nonattainment','supporting-line-bound-and-continuous-recovery','The mean constraint interacts with a nonconvex two-well cost: a supporting envelope gives the infimum, while continuous recovery sequences and incompatible endpoint values decide attainment.','The capped-density construction uses indicator extrema which are admissible; here continuity makes mixed phases only limiting objects and the endpoint data prevent attainment.',indices=range(12),prerequisites=['integral inequalities','continuous approximation','convex supporting lines'])
def relaxation(fid,i):
 mu=RELAX_MEANS[i];A=s.Integer(0) if mu<=1 else (mu*mu-1)**2;wrong=(mu*mu-1)**2 if mu<1 else R(1,16) if mu==1 else (mu-1)**2
 assert wrong!=A
 combos=[(A,False),(wrong,False),(A,True),(wrong,True)]
 def form(v,b):return r'\left('+L(v)+r',\ \textnormal{'+('yes' if b else 'no')+r'}\right)'
 opts=[(str(v)+';'+str(b),form(v,b),'correct' if j==0 else 'Assume the cost at the mean equals the relaxed minimum' if j==1 and mu<1 else 'Replace the quartic supporting cost by one well-distance squared' if j==1 else 'Treat a discontinuous phase mixture or incompatible constant as admissible' if j==2 else 'Combine the pointwise cost and attainment mistakes') for j,(v,b) in enumerate(combos)]
 Q=T('Let f range over continuous real functions satisfying the displayed range, endpoint values and mean. Find the ordered pair consisting of the infimum of J and the answer yes or no to whether it is attained.')+r'\quad -2\le f(x)\le2\quad(0\le x\le1),\quad f(0)=-2,\quad f(1)=2,\quad\int_0^1f(x)\,\mathrm{d}x='+L(mu)+r',\qquad J(f)=\int_0^1(f(x)^2-1)^2\,\mathrm{d}x.'
 steps=[T('The nonconvex cost has two zero wells. The best lower bound must allow mixtures of those wells rather than apply Jensen directly to the quartic.'),r'W(y)=(y^2-1)^2,\qquad\mu='+L(mu)+r'.']
 if mu<=1:
  steps += [T('Nonnegativity gives a lower bound of zero. A measurable mixture with the prescribed mean takes the two well values in the following proportions.'),r'\lambda=\frac{1+\mu}{2},\qquad\lambda\cdot1+(1-\lambda)(-1)=\mu,\qquad\lambda W(1)+(1-\lambda)W(-1)=0.']
  if mu<1:
   steps += [T('For a strictly mixed mean, put the single interior transition at t zero as follows. Use linear ramps from minus two to minus one on the first interval, from minus one to one across the middle interval, and from one to two on the last interval. On the remaining intervals keep the neighboring well value.'),r't_0=(1-\mu)/2,\quad0<\delta<\tfrac12\min(t_0,1-t_0),\qquad [0,\delta],\quad[t_0-\delta,t_0+\delta],\quad[1-\delta,1].',r'\int_0^1f_\delta(x)\,\mathrm{d}x=1-2t_0=\mu,\qquad J(f_\delta)=\frac{92}{15}\delta\to0.']
  else:
   steps += [T('For the pure-well mean, keep the middle value slightly above one and connect linearly to the endpoint values on intervals of length delta. This preserves the mean exactly and makes the cost tend to zero.'),r'0<\delta<1/2,\qquad c_\delta=\frac1{1-\delta},\qquad\int_0^1f_\delta(x)\,\mathrm{d}x=(1-\delta)c_\delta=1,\quad J(f_\delta)\to W(1)=0.']
 else:
  steps += [T('Above the right well, the tangent at the required mean is a global supporting line, even though the quartic is not globally convex. The following factorization proves it directly.'),r'W(y)-W(\mu)-W\prime(\mu)(y-\mu)=(y-\mu)^2\big((y+\mu)^2+2\mu^2-2\big)\ge0.',r'J(f)\ge W(\mu)+W\prime(\mu)\left(\int_0^1f(x)\,\mathrm{d}x-\mu\right)=W(\mu)='+L(A)+r'.',T('To approach this bound continuously, keep f constant on the middle interval and connect linearly to the two endpoint values on intervals of length delta. The middle value can be chosen to preserve the mean exactly.'),r'c_\delta=\frac{\mu}{1-\delta},\quad 0<\delta<1-\mu/2,\qquad f_\delta(x)=\begin{cases}-2+(c_\delta+2)x/\delta,&0\le x\le\delta,\\c_\delta,&\delta\le x\le1-\delta,\\c_\delta+(2-c_\delta)(x-1+\delta)/\delta,&1-\delta\le x\le1,\end{cases}',r'\int_0^1f_\delta(x)\,\mathrm{d}x=(1-\delta)c_\delta=\mu,\qquad J(f_\delta)\to W(\mu).']
 if mu<=1:
  steps += [T('Attaining zero cost would force the continuous function to take only the two well values everywhere. It could not have either of the prescribed endpoint values; by continuity an endpoint neighborhood already has positive cost.')]
 else:
  steps += [T('The supporting-line defect is strictly positive except at the mean, because the mean exceeds one. Equality would therefore force f to be constantly equal to its mean, contradicting the prescribed endpoint values.')]
 steps += [T('Thus the lower bound is an infimum reached by a sequence, and is not attained by any admissible continuous function.'),opts[0][1]]
 y,z=s.symbols('y z',real=True);W=(y*y-1)**2
 checks=[eq('Global tangent defect factorization',W-(z*z-1)**2-4*z*(z*z-1)*(y-z),(y-z)**2*((y+z)**2+2*z*z-2)),truth('Prescribed mean is strictly inside the range',-2<mu<2)]
 cert=['For means inside the two wells, nonnegativity supplies the lower bound and a two-phase mixture supplies its measurable value. One can approximate that mixture by a continuous piecewise linear function on shrinking transition intervals while enforcing the mean exactly: for a strictly mixed mean adjust a phase length, and for the pure mean one adjust the middle level slightly above or below the well. These adjustments tend to zero and stay inside[-2,2] for small transition lengths; the cost is bounded on the allowed range, so shrinking transitions have vanishing cost. For means above one, the exact tangent-defect factorization gives a global lower bound without an invalid Jensen invocation on the quartic. The explicitly displayed constant-middle recovery function has exact mean and remains inside the allowed range for the stated delta interval; dominated convergence gives its cost limit. Continuous endpoint incompatibility prevents zero cost in the mixed regime, while strict supporting-line equality forces a forbidden constant in the outer regime.']
 return package({k:v for k,v in FAMILIES[fid].items() if k!='fn'},i,Q,opts,opts[0][0],steps,checks,cert,parameters={'mean':str(mu),'normalizedCapacityKey':'fixed-quartic-fixed-endpoints-mean:'+str(mu),'purposefulCase':'Includes strictly mixed phase fractions, the pure-well transition and outer strictly supported means. Reflection-equivalent negative means are excluded; the fixed quartic and endpoint values preclude scaling one constraint into another.'})

@register('nonlinear-uniform-bound-threshold','Osgood-integral-blowup-threshold','nonlinear-integral-comparison-and-truncated-extremizers','A nonlinear integral inequality has a sharp finite-time uniform-boundedness threshold; the critical time itself must be ruled out by finite continuous truncated trajectories.','The ODE Osgood family concerns uniqueness of a prescribed differential equation. Here an entire class of continuous subsolutions is uniformly bounded only before the blowup integral, and each counterexample remains finite.',prerequisites=['monotone comparison','inverse integral functions','improper integrals'])
def osgood_threshold(fid,i):
 p=i+2;C=s.pi*s.binomial(2*p-2,p-1)/(2*4**(p-1));wrong=C*(2 if i%2==0 else R(1,2))
 def form(c,closed):return r'0<T'+(r'\le' if closed else '<')+L(c)
 vals=[(C,False),(C,True),(wrong,False),(wrong,True)];opts=[(str(c)+';'+str(b),form(c,b),'correct' if j==0 else 'Include the critical time because each individual subsolution is finite' if j==1 else 'Lose a half-line factor in the blowup integral' if j==2 else 'Combine the critical-endpoint and half-line normalization errors') for j,(c,b) in enumerate(vals)]
 Q=T('For which positive T does there exist a finite bound B, depending only on T, such that every continuous nonnegative u satisfying the displayed integral inequality also satisfies the displayed uniform bound?')+r'\quad u(t)\le\int_0^t(1+u(s)^2)^{'+str(p)+r'}\,\mathrm{d}s\quad(0\le t\le T),\qquad\sup_{0\le t\le T}u(t)\le B.'
 steps=[T('Compare the entire class with the increasing trajectory generated by the reciprocal growth integral. Define the growth function and its increasing integral.'),r'\omega(y)=(1+y^2)^{'+str(p)+r'},\qquad G(y)=\int_0^y\frac{\mathrm{d}z}{\omega(z)},\qquad T_* =\int_0^\infty\frac{\mathrm{d}z}{\omega(z)}.',T('For an arbitrary admissible u, its accumulated right side is a differentiable majorant v. Monotonicity of the growth function gives an upper differential inequality for v.'),r'v(t)=\int_0^t\omega(u(s))\,\mathrm{d}s,\quad0\le u(t)\le v(t),\quad v(0)=0,\quad v\prime(t)=\omega(u(t))\le\omega(v(t)).',r'\frac{\mathrm{d}}{\mathrm{d}t}G(v(t))=\frac{v\prime(t)}{\omega(v(t))}\le1,\qquad G(v(t))\le t.',T('Before the limiting value of G, invert this inequality. It gives one finite bound for every member of the class.'),r'T<T_*\quad\Longrightarrow\quad u(t)\le v(t)\le G^{-1}(T)\quad(0\le t\le T).',T('To test the critical endpoint, fix any positive N and follow the exact increasing trajectory until it reaches N. Then keep it constant. Define that finite continuous function as follows.'),r't_N=G(N)<T_*,\qquad u_N(t)=\begin{cases}G^{-1}(t),&0\le t\le t_N,\\N,&t_N\le t\le T.\end{cases}',T('Up to the joining time it satisfies equality in the integral equation. Afterwards the right side keeps increasing, while the function stays at N. Thus it remains an admissible subsolution.'),r'\int_0^t\omega(u_N(s))\,\mathrm{d}s=N+(t-t_N)\omega(N)\ge N=u_N(t)\quad(t\ge t_N).',T('If T reaches or exceeds the critical time, all such truncated trajectories fit in the interval. Their heights are unbounded as N increases, so no common finite bound exists. Evaluate the critical integral by a tangent substitution and the cosine-power recurrence.'),r'T_* =\int_0^{\pi/2}\cos^{'+str(2*p-2)+r'}\theta\,\mathrm{d}\theta=\frac\pi2\frac{\binom{'+str(2*p-2)+'}{'+str(p-1)+r'}}{4^{'+str(p-1)+r'}}='+L(C)+r'.',opts[0][1]]
 checks=[truth('Nonlinear growth is increasing on the nonnegative half-line',p>=2),eq('Tangent Jacobian yields the displayed cosine exponent',2*p-2,2*(p-1)),eq('Cosine recurrence coefficient',s.prod(R(2*j-1,2*j) for j in range(1,p)),s.binomial(2*p-2,p-1)/4**(p-1))]
 cert=['Every continuous admissible u is finite on its compact interval, so v is continuously differentiable and the chain rule applies. The growth function is positive and increasing for nonnegative inputs, yielding the majorant comparison. G is strictly increasing from zero to a finite limit; below that limit its inverse exists and is finite. The exact inverse trajectory is differentiable and solves y-prime=omega(y) before blowup by the inverse function theorem. The truncated trajectory is continuous at its joining point and need not be differentiable there, which is allowed by the question. Its integral inequality is checked explicitly after the join. Therefore individual finite counterexamples of arbitrary height exist even at the critical time itself. The tangent substitution and finite cosine-power recurrence evaluate the positive improper integral; its decay at infinity is z^(-2p), ensuring convergence.']
 return package({k:v for k,v in FAMILIES[fid].items() if k!='fn'},i,Q,opts,opts[0][0],steps,checks,cert,parameters={'growthPower':p,'normalizedCapacityKey':'nonlinear-growth-degree:'+str(2*p),'purposefulCase':'Different nonlinear growth degrees change the comparison dynamics and blowup integral; no amplitude or time scaling changes one degree into another. Every instance includes the sharp critical-endpoint distinction.'})
